function BhPortfolio() {
  const [view,setView]=useState('Theme-wise');
  const [region,setRegion]=useState('All Regions'),[crop,setCrop]=useState('All Crops'),[product,setProduct]=useState('All Products'),[theme,setTheme]=useState('All Themes'),[period,setPeriod]=useState('YTD');
  const base=[{name:'Retailer-Led Croptek Conversion',theme:'Conversion & Adoption',region:'West Region',crop:'Onion',product:'Croptek',quarter:4,investment:9,adopters:180,planned:80,observed:72},{name:'Product Adoption Drive',theme:'Conversion & Adoption',region:'West Region',crop:'Maize',product:'Saarthi',quarter:3,investment:23,adopters:260,planned:84,observed:80},{name:'Retailer Enablement',theme:'Retailer Enablement',region:'West Region',crop:'Onion',product:'Croptek',quarter:4,investment:22,adopters:180,planned:82,observed:76},{name:'Trial & Follow-up',theme:'Trial & Follow-up',region:'West Region',crop:'Onion',product:'Croptek',quarter:2,investment:18,adopters:140,planned:82,observed:76},{name:'Conversion Field Drive',theme:'Conversion & Adoption',region:'South Region',crop:'Onion',product:'Saarthi',quarter:4,investment:18,adopters:180,planned:78,observed:71},{name:'Retailer Network Drive',theme:'Retailer Enablement',region:'South Region',crop:'Maize',product:'Croptek',quarter:1,investment:16,adopters:150,planned:78,observed:71},{name:'Crop Awareness',theme:'Crop Nutrition Awareness',region:'South Region',crop:'Onion',product:'Croptek',quarter:4,investment:14,adopters:160,planned:78,observed:71},{name:'Adoption Trial',theme:'Conversion & Adoption',region:'North Region',crop:'Maize',product:'Croptek',quarter:2,investment:14,adopters:180,planned:74,observed:68},{name:'Farmer Trial',theme:'Trial & Follow-up',region:'North Region',crop:'Onion',product:'Saarthi',quarter:4,investment:16,adopters:90,planned:74,observed:68},{name:'Nutrition Awareness',theme:'Crop Nutrition Awareness',region:'North Region',crop:'Maize',product:'Croptek',quarter:1,investment:14,adopters:100,planned:74,observed:68},{name:'Retailer Activation',theme:'Retailer Enablement',region:'East Region',crop:'Onion',product:'Saarthi',quarter:4,investment:10,adopters:100,planned:68,observed:66},{name:'East Trial Drive',theme:'Trial & Follow-up',region:'East Region',crop:'Maize',product:'Croptek',quarter:3,investment:16,adopters:140,planned:70,observed:66}];
  const filtered=base.filter(c=>(region==='All Regions'||c.region===region)&&(crop==='All Crops'||c.crop===crop)&&(product==='All Products'||c.product===product)&&(theme==='All Themes'||c.theme===theme)&&(period==='YTD'||(period==='QTD'?c.quarter>=3:c.quarter===4)));
  const investment=filtered.reduce((s,c)=>s+c.investment,0),adopters=filtered.reduce((s,c)=>s+c.adopters,0),execution=filtered.length?Math.round(filtered.reduce((s,c)=>s+c.observed,0)/filtered.length):0;
  const groups:Record<string,typeof base>={};filtered.forEach(c=>{const key=view==='Theme-wise'?c.theme:view==='Crop-wise'?c.crop:view==='Product-wise'?c.product:c.region;(groups[key]??=[]).push(c)});
  const groupedRows=Object.entries(groups).map(([name,items])=>[name,items.length,`₹${items.reduce((s,c)=>s+c.investment,0)} L`,items.reduce((s,c)=>s+c.adopters,0).toLocaleString(),'Pending attribution','Pending attribution'] as (string|number)[]);
  const regionRows=['West Region','South Region','North Region','East Region'].map(r=>{const items=filtered.filter(c=>c.region===r);return [r.replace(' Region',''),...themes.map(t=>items.filter(c=>c.theme===t.name).length),items.length] as (string|number)[]}).filter(r=>Number(r.at(-1))>0);
  const adopterBars=Object.entries(groups).map(([label,items])=>({label,value:items.reduce((s,c)=>s+c.adopters,0),note:items.reduce((s,c)=>s+c.adopters,0).toLocaleString()}));
  return <BhPage screen="bh.2" subtitle="Compare campaign performance across themes, crops, products and geographies. Financial outcomes remain provisional until attribution is validated.">
    <div className="bh-filterbar"><label>Region<select value={region} onChange={e=>setRegion(e.target.value)}><option>All Regions</option>{regions.map(r=><option key={r.name}>{r.name}</option>)}</select></label><label>Crop<select value={crop} onChange={e=>setCrop(e.target.value)}><option>All Crops</option><option>Onion</option><option>Maize</option></select></label><label>Product<select value={product} onChange={e=>setProduct(e.target.value)}><option>All Products</option><option>Croptek</option><option>Saarthi</option></select></label><label>Theme<select value={theme} onChange={e=>setTheme(e.target.value)}><option>All Themes</option>{themes.map(t=><option key={t.name}>{t.name}</option>)}</select></label><label>Period<select value={period} onChange={e=>setPeriod(e.target.value)}><option>YTD</option><option>QTD</option><option>Monthly</option></select></label></div>
    <div className="bh-tabs" role="tablist">{['Theme-wise','Crop-wise','Product-wise','Geography-wise'].map(t=><button role="tab" aria-selected={view===t} className={view===t?'active':''} key={t} onClick={()=>setView(t)}>{t}</button>)}</div>
    <div className="bh-metrics four"><BhMetric label="Active campaigns" value={String(filtered.length)} note={`Across ${new Set(filtered.map(c=>c.region)).size} regions`}/><BhMetric label="Actual marketing investment" value={`₹${(investment/100).toFixed(2)} Cr`} note={`${investment} L selected`}/><BhMetric label="Recorded adopters" value={adopters.toLocaleString()}/><BhMetric label="Average regional execution" value={`${execution}%`} note="Observed progress" tone="amber"/></div>
    <BhCard title={`Campaign performance (${view.toLowerCase()})`}>{filtered.length?<Table headers={[view==='Theme-wise'?'Theme':view==='Geography-wise'?'Region':'Segment','Active campaigns','Marketing investment','Recorded adopters','Incremental sales','Net ROI']} rows={groupedRows}/>:<p className="bh-copy">No campaigns match the selected filters.</p>}</BhCard>
    <div className="bh-grid two"><BhCard title="Region × theme · active campaign count"><Table headers={['Region','Conversion','Retailer','Trial','Awareness','Total']} rows={regionRows}/></BhCard><BhCard title={`Recorded adopters by ${view.replace('-wise','').toLowerCase()}`}><BhBars items={adopterBars}/></BhCard></div>
    <div className="bh-actions"><LinkRow label="Explore regional performance" to="bh.3"/><LinkRow label="Campaign effectiveness" to="bh.4"/><LinkRow label="Marketing spend & ROI" to="bh.5"/></div>
  </BhPage>;
}

